package org.beyondlight;
import java.util.*;import java.util.regex.*;
/** Deterministic equation composition and bounded least-squares candidate search. */
public final class Discovery {
 public record Combined(String expression,String shared,String derivation,String dimensions,String classification,double residual){}
 private Discovery(){}
 public static Combined combine(EquationRegistry.Equation a,EquationRegistry.Equation b,String shared,String variableDims,String values){if(shared.isBlank())throw new IllegalArgumentException("select a shared variable to eliminate");Map<String,Dimensions.D> dims=EquationRegistry.dimensions(variableDims);Dimensions.equationBalanced(a.lhs(),a.rhs(),dims);Dimensions.equationBalanced(b.lhs(),b.rhs(),dims);Set<String> va=vars(a.lhs()+" "+a.rhs()),vb=vars(b.lhs()+" "+b.rhs());if(!va.contains(shared)||!vb.contains(shared))throw new IllegalArgumentException("selected variable is not present in both equations");String expression=Symbolic.isolate(a.lhs(),a.rhs(),shared);String left=Symbolic.substitute(b.lhs(),shared,expression),right=Symbolic.substitute(b.rhs(),shared,expression);Dimensions.equationBalanced(left,right,dims);String result=left+" = "+right;String steps="1. Source A: "+a.name()+" ("+a.lhs()+" = "+a.rhs()+")\n2. Isolate "+shared+": "+shared+" = "+expression+"\n3. Source B: "+b.name()+" ("+b.lhs()+" = "+b.rhs()+")\n4. Substitute: "+result+"\n5. SI dimensions balanced: "+Dimensions.of(Symbolic.parse(left),dims);double residual=Double.NaN;if(!values.isBlank()){Map<String,Double> v=numbers(values);double x=Symbolic.evaluate(left,v),y=Symbolic.evaluate(right,v);residual=x-y;steps+="\n6. Numeric evaluation: left="+x+", right="+y+", residual="+residual;}return new Combined(result,shared,steps,Dimensions.of(Symbolic.parse(left),dims).toString(),"MATHEMATICALLY DERIVED",residual);}
 private static Set<String> vars(String s){Set<String>x=new TreeSet<>();Matcher m=Pattern.compile("[A-Za-z_][A-Za-z_0-9]*").matcher(s);while(m.find()){String n=m.group();if(!Set.of("sqrt","sin","cos","ln","exp","pi","e").contains(n))x.add(n);}return x;}
 public static Map<String,Double> numbers(String s){Map<String,Double> m=new HashMap<>();for(String p:s.split(",")){if(p.isBlank())continue;String[]a=p.trim().split("=",2);if(a.length!=2)throw new IllegalArgumentException("use name=number pairs");double d=Double.parseDouble(a[1]);if(!Double.isFinite(d))throw new IllegalArgumentException("nonfinite value");m.put(a[0].trim(),d);}return m;}
 public record Candidate(String expression,String algorithm,double[] parameters,double rmse,double rSquared,String classification,int points){}
 public static List<Candidate> search(String xs,String ys,int limit){String[]xa=xs.split(","),ya=ys.split(",");if(xa.length!=ya.length||xa.length<3||xa.length>10000)throw new IllegalArgumentException("matching x,y arrays of 3..10000 points required");if(limit<1||limit>12)throw new IllegalArgumentException("candidate limit must be 1..12");double[]x=new double[xa.length],y=new double[ya.length];for(int i=0;i<x.length;i++){x[i]=Double.parseDouble(xa[i].trim());y[i]=Double.parseDouble(ya[i].trim());if(!Double.isFinite(x[i])||!Double.isFinite(y[i]))throw new IllegalArgumentException("data must be finite");}List<Candidate>out=new ArrayList<>();for(int degree=1;degree<=4;degree++){double[]p=fit(x,y,degree);if(p!=null)add(out,x,y,p,"polynomial degree "+degree,"y = polynomial degree "+degree);}if(Arrays.stream(x).allMatch(v->v>0)){double[]lx=Arrays.stream(x).map(Math::log).toArray();double[]p=fit(lx,y,1);if(p!=null)add(out,x,y,p,"logarithmic","y = "+p[0]+" + "+p[1]+"*ln(x)");double[]rx=Arrays.stream(x).map(v->1/v).toArray();p=fit(rx,y,1);if(p!=null)add(out,x,y,p,"reciprocal","y = "+p[0]+" + "+p[1]+"/x");}if(Arrays.stream(y).allMatch(v->v>0)){double[]ly=Arrays.stream(y).map(Math::log).toArray();double[]p=fit(x,ly,1);if(p!=null)add(out,x,y,new double[]{Math.exp(p[0]),p[1]},"exponential","y = "+Math.exp(p[0])+"*exp("+p[1]+"*x)");}if(Arrays.stream(x).allMatch(v->v>0)&&Arrays.stream(y).allMatch(v->v>0)){double[]lx=Arrays.stream(x).map(Math::log).toArray(),ly=Arrays.stream(y).map(Math::log).toArray(),p=fit(lx,ly,1);if(p!=null)add(out,x,y,new double[]{Math.exp(p[0]),p[1]},"power law","y = "+Math.exp(p[0])+"*x^"+p[1]);}out.sort(Comparator.comparingDouble(Candidate::rmse));return List.copyOf(out.subList(0,Math.min(limit,out.size())));}
 private static void add(List<Candidate>out,double[]x,double[]y,double[]p,String algorithm,String expression){double sse=0,mean=Arrays.stream(y).average().orElse(0),sst=0;for(int i=0;i<x.length;i++){double pred=predict(algorithm,p,x[i]);if(!Double.isFinite(pred))return;sse+=Math.pow(y[i]-pred,2);sst+=Math.pow(y[i]-mean,2);}out.add(new Candidate(expression,algorithm,p,Math.sqrt(sse/x.length),sst==0?Double.NaN:1-sse/sst,algorithm.equals("polynomial degree 1")||algorithm.equals("polynomial degree 2")?"NUMERICALLY OBSERVED":"HYPOTHESIS — UNVERIFIED",x.length));}
 static double predict(String algorithm,double[]p,double x){if(algorithm.startsWith("polynomial")){double y=0;for(int i=p.length-1;i>=0;i--)y=y*x+p[i];return y;}return switch(algorithm){case "logarithmic"->p[0]+p[1]*Math.log(x);case "reciprocal"->p[0]+p[1]/x;case "exponential"->p[0]*Math.exp(p[1]*x);case "power law"->p[0]*Math.pow(x,p[1]);default->Double.NaN;};}
 public static void save(java.nio.file.Path path,String record){try{java.nio.file.Files.createDirectories(path.getParent());java.nio.file.Files.writeString(path,record+"\n",java.nio.charset.StandardCharsets.UTF_8,java.nio.file.StandardOpenOption.CREATE,java.nio.file.StandardOpenOption.APPEND);}catch(java.io.IOException e){throw new IllegalStateException("candidate archive failed: "+e.getMessage());}}
 private static double[]fit(double[]x,double[]y,int d){int n=d+1;double[][]a=new double[n][n+1];for(int r=0;r<n;r++){for(int c=0;c<n;c++)for(double v:x)a[r][c]+=Math.pow(v,r+c);for(int i=0;i<x.length;i++)a[r][n]+=Math.pow(x[i],r)*y[i];}for(int i=0;i<n;i++){int b=i;for(int r=i+1;r<n;r++)if(Math.abs(a[r][i])>Math.abs(a[b][i]))b=r;if(Math.abs(a[b][i])<1e-20)return null;double[]t=a[i];a[i]=a[b];a[b]=t;double q=a[i][i];for(int c=i;c<=n;c++)a[i][c]/=q;for(int r=0;r<n;r++)if(r!=i){q=a[r][i];for(int c=i;c<=n;c++)a[r][c]-=q*a[i][c];}}double[]p=new double[n];for(int i=0;i<n;i++)p[i]=a[i][n];return p;}
}
